from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Loop through the input string to identify and separate each group of nested parentheses
    groups = []
    current_group = ""
    for char in paren_string:
        if char == "(":
            if current_group:
                groups.append(current_group)
            current_group = "("
        elif char == ")":
            current_group += ")"
            groups.append(current_group)
            current_group = ""

    # Check if each group is balanced and properly closed
    result = []
    for group in groups:
        if group.count("(") == group.count(")"):
            result.append(group)

    # Return the list of separated groups
    return result

